 {FakeLogind service(bus.address);Events unsupported;check(!unsupported.start()&&unsupported.snapshot().state==State::Unsupported&&!unsupported.snapshot().admissionReady()&&service.acquisitions==0,"default has no bus/inhibitor authority");auto c=config(bus.address);c.route.scope=Scope::VerifiedPlatform;Events noPromotion(c);check(!noPromotion.start()&&noPromotion.snapshot().reason==Reason::InvalidConfiguration&&service.acquisitions==0,"private address cannot assert platform readiness");c=config(bus.address);c.route.allRelevantSleepRoutes=false;Events uncovered(c);check(!uncovered.start()&&service.acquisitions==0,"signal availability cannot qualify unverified coverage");}
 {FakeLogind service(bus.address);Events e(config(bus.address));check(e.start(),"start private backend");auto initial=ready(e);check(!e.acknowledgeQuiesced(initial.generation),"no early quiescence ack");forged(bus.address);until([&]{return e.snapshot().foreignSignals==1;});check(e.snapshot().state==State::FixtureReady,"foreign service signal ignored");forged(bus.address,"/wrong");forged(bus.address,"/org/freedesktop/login1","org.example.Other");std::this_thread::sleep_for(std::chrono::milliseconds(10));check(e.snapshot().state==State::FixtureReady,"wrong path and interface cannot signal sleep");service.signal(true);until([&]{return e.snapshot().state==State::Preparing;});auto preparing=e.snapshot();check(preparing.generation>initial.generation&&!preparing.admissionReady()&&preparing.deadlineBoottimeUsec<=service.emittedBoot+200000,"sleep seals generation with conservative finite deadline");check(!e.acknowledgeQuiesced(initial.generation),"old generation ack rejected");auto deadline=preparing.deadlineBoottimeUsec;service.signal(true);until([&]{return e.snapshot().duplicateSignals==1;});check(e.snapshot().deadlineBoottimeUsec==deadline&&e.snapshot().generation==preparing.generation,"duplicate sleep never extends allowance");check(e.acknowledgeQuiesced(preparing.generation),"current generation quiesced ack");check(closed(e).reason==Reason::Quiesced&&e.finish(100),"quiescence closes worker");until([&]{return service.released==1;});service.signal(false);check(!e.start()&&e.snapshot().state==State::Closed&&service.acquisitions==1,"wake never reacquires or readmits");}
 {FakeLogind service(bus.address);Events e(config(bus.address));check(e.start(),"expiry start");ready(e);service.signal(true);until([&]{return e.snapshot().state==State::Preparing;});auto p=e.snapshot();check(closed(e).reason==Reason::DelayExpired&&usec(CLOCK_BOOTTIME)>=p.deadlineBoottimeUsec,"finite allowance releases without ack");check(!e.acknowledgeQuiesced(p.generation)&&e.finish(100),"late ack rejected");until([&]{return service.released==1;});}
